"""Which repository and service each request uses. Change the implementations here."""

from fastapi import Depends, Request
from sqlalchemy.orm import Session

from app.db import get_session
from app.repositories.customer import CustomerRepository, SqlCustomerRepository
from app.repositories.order import OrderRepository, SqlOrderRepository
from app.repositories.product import ProductRepository, SqlProductRepository
from app.services.customer import CustomerService
from app.services.order import OrderService
from app.services.product import ProductService


def get_customer_repository(session: Session = Depends(get_session)) -> CustomerRepository:
    """The storage of customers."""
    return SqlCustomerRepository(session)


def get_customer_service(
    repository: CustomerRepository = Depends(get_customer_repository),
) -> CustomerService:
    """The service of customers, with the storage of the resources it refers to."""
    return CustomerService(repository)


def get_product_repository(session: Session = Depends(get_session)) -> ProductRepository:
    """The storage of products."""
    return SqlProductRepository(session)


def get_product_service(
    repository: ProductRepository = Depends(get_product_repository),
) -> ProductService:
    """The service of products, with the storage of the resources it refers to."""
    return ProductService(repository)


def get_order_repository(session: Session = Depends(get_session)) -> OrderRepository:
    """The storage of orders."""
    return SqlOrderRepository(session)


def get_order_service(
    repository: OrderRepository = Depends(get_order_repository),
    customers: CustomerRepository = Depends(get_customer_repository),
    products: ProductRepository = Depends(get_product_repository),
) -> OrderService:
    """The service of orders, with the storage of the resources it refers to."""
    return OrderService(repository, customers, products)

